return ['domain'=>'shd-instagram-feed','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'SHD Instagram Feed 0.5.0','pot-creation-date'=>'2026-11-09T13:24:25+00:00','po-revision-date'=>'2026-11-09 13:22+0000','messages'=>['SHD Instagram Feed'=>'SHD Instagram Feed','https://www.sh-digital.ch/'=>'https://www.sh-digital.ch/','Shows your latest Instagram posts in a fast, accessible slider with an Elementor widget. Posts and images are synced in the background and stored locally, so visitors never load anything from Instagram.'=>'Zeigt Ihre neuesten Instagram-Beiträge in einem schnellen, barrierefreien Slider mit Elementor-Widget. Beiträge und Bilder werden im Hintergrund synchronisiert und lokal gespeichert, Besucher laden also nichts von Instagram.','SH Digital'=>'SH Digital','Instagram Feed'=>'Instagram-Feed','Settings'=>'Einstellungen','Posts to keep'=>'Gespeicherte Beiträge','Check for new posts'=>'Nach neuen Beiträgen suchen','The newest posts are kept with their images; older images are deleted automatically. When only ticked posts are shown, ticked posts are kept in addition.'=>'Die neuesten Beiträge werden mit ihren Bildern gespeichert; ältere Bilder werden automatisch gelöscht. Wenn nur angehakte Beiträge gezeigt werden, bleiben angehakte Beiträge zusätzlich gespeichert.','Every hour'=>'Stündlich','Twice a day'=>'Zweimal täglich','Once a day'=>'Einmal täglich','Please paste an access token.'=>'Bitte fügen Sie ein Zugriffstoken ein.','Disconnected. The cached posts and images were deleted.'=>'Verbindung getrennt. Die gespeicherten Beiträge und Bilder wurden gelöscht.','Disconnected. The widget keeps showing the cached posts until you connect again.'=>'Verbindung getrennt. Das Widget zeigt weiterhin die gespeicherten Beiträge, bis Sie das Konto wieder verbinden.','Saved. %1$d of %2$d post is shown on the website.'=>'Gespeichert. %1$d von %2$d Beitrag wird auf der Website gezeigt.' . "\0" . 'Gespeichert. %1$d von %2$d Beiträg